from backtester import Strategy

class MyStrategy(Strategy):
    def init(self, ctx):
        self.sma_10 = None
        self.sma_30 = None

    def on_bar(self, ctx):
        if len(ctx.history()) < 30:
            return

        close = ctx.history()['close']
        self.sma_10 = close.rolling(window=10).mean()
        self.sma_30 = close.rolling(window=30).mean()

        if self.sma_10.iloc[-1] > self.sma_30.iloc[-1] and ctx.position() == 0:
            ctx.order_target_percent(0.95)
        elif self.sma_10.iloc[-1] <= self.sma_30.iloc[-1] and ctx.position() != 0:
            ctx.close_position()

strategy = MyStrategy()

