class MyStrategy(Strategy):
    def init(self, ctx):
        self.sma_window = 100
        self.warmup = self.sma_window

    def on_bar(self, ctx):
        if len(ctx.history()) < self.warmup:
            return

        sma = ctx.history().close.rolling(window=self.sma_window).mean()
        current_price = ctx.price()

        if current_price > sma.iloc[-1]:
            ctx.order_target_percent(0.95)
        elif current_price < sma.iloc[-1]:
            ctx.close_position()

strategy = MyStrategy()

