import numpy as np

class RatioMeanReversion(Strategy):
    def __init__(self):
        self.ratios = []

    def on_bar(self, ctx):
        if len(ctx.history('XXX')) < 20:
            return

        ratio = ctx.price('XXX') / ctx.price('YYY')
        self.ratios.append(ratio)
        self.ratios = self.ratios[-20:]

        mean_ratio = np.mean(self.ratios)
        std_ratio = np.std(self.ratios, ddof=1)
        z = (ratio - mean_ratio) / std_ratio

        if ctx.position('XXX') == 0 and z < -2:
            ctx.order_target_percent(0.95, 'XXX')
        elif ctx.position('XXX') > 0 and z > 0:
            ctx.close_position('XXX')

strategy = RatioMeanReversion()

