class NormalizedPriceStrategy(Strategy):
    def init(self, ctx):
        self.high_close = None

    def on_bar(self, ctx):
        if len(ctx.history()) < 2:
            return

        if self.high_close is None:
            self.high_close = ctx.history()['close'].max()

        normalized_close = ctx.price() / self.high_close

        if normalized_close < 0.5:
            ctx.order_target_percent(0.95)
        elif normalized_close > 0.8:
            ctx.close_position()

strategy = NormalizedPriceStrategy()

