class LeverageStrategy(Strategy):
    def __init__(self):
        self.sma_window = 50
        self.position = 0

    def init(self, ctx):
        ctx.order_target_percent(0)

    def on_bar(self, ctx):
        if len(ctx.history()) < self.sma_window:
            return

        sma = ctx.history().close.rolling(window=self.sma_window).mean()
        current_sma = sma.iloc[-1]
        previous_sma = sma.iloc[-2]

        if current_sma > previous_sma:
            target_value = ctx.equity * 3
            target_position = target_value / ctx.price()
            ctx.order_target_quantity(target_position)
        else:
            ctx.close_position()

strategy = LeverageStrategy()

