class GoldenCrossStrategy(Strategy):
    def __init__(self):
        self.short_selling_allowed = False
        self.initial_cash = 100000
        self.symbol = 'ASSET'
        self.sma_short = 50
        self.sma_long = 200
        self.position = 0

    def init(self, ctx):
        pass

    def on_bar(self, ctx):
        if len(ctx.history()) < self.sma_long:
            return

        short_sma = ctx.history().close.rolling(window=self.sma_short).mean()
        long_sma = ctx.history().close.rolling(window=self.sma_long).mean()

        if short_sma.iloc[-1] > long_sma.iloc[-1] and short_sma.iloc[-2] <= long_sma.iloc[-2]:
            if self.position == 0:
                ctx.buy(ctx.cash / ctx.price(), self.symbol)
                self.position = ctx.position(self.symbol)
        elif short_sma.iloc[-1] < long_sma.iloc[-1] and short_sma.iloc[-2] >= long_sma.iloc[-2]:
            if self.position > 0:
                ctx.sell(self.position, self.symbol)
                self.position = 0

strategy = GoldenCrossStrategy()
